from __future__ import annotations

import base64
import io
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TARGET = ROOT / "build/generated/metatech_assets"

# Approved machine textures ported as complete 16x16 Minecraft assets.
# GUI concept sheets are deliberately not included.
ARCHIVE = "...TRUNCATED_FOR_REWRITE..."


def main() -> None:
    payload = base64.b64decode(ARCHIVE)
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        archive.extractall(TARGET)
    print(f"Installed {len(archive.namelist())} approved 0.6.77 assets")


if __name__ == "__main__":
    main()
